// Petshop Sprendimai Shortcode Variklis v9
// v1: baziniai shortcode'ai + AV saugumo taisyklė
// v2: vizualus stiprinimas pagal konsultanto review — hero, CTA banneris, pilno pločio grid'ai,
//     didesnės kortelės, mobile limitas 6/grid'e (CSS), footer product widget'ų slėpimas Sprendimai puslapiuose,
//     ryškesnis FAQ accordion (+/− indikatorius)
// v3: CTA padding mažesnis, rinkinių kortelė be nuotraukos -> 🎁 ikona, produktų img object-fit:contain, FAQ border/bg
// v4: mobile CTA kortelės daugiau oro, didesnis tarpas tarp Šunims/Katėms grid sekcijų
// v5: naujas [psc_sprendimas_krypties_kortele] — navigacinė pasirinkimo kortelė
// v6: krypties kortelės 2+2 desktop, mobile daugiau oro, antrinė nuoroda link-button
// v7: antrinė nuoroda = outline mygtukas mygtukų eilėje
// v8: krypties kortelė palaiko single_title/single_url
// v9: 3-stulpelių grid variantas (.psc-sol-krypt-grid-3) 5 kortelėms + graužikų footnote stilius (.psc-sol-footnote)

if (!function_exists('psc_sprendimas_resolve_source')) {
    function psc_sprendimas_resolve_source($pid){
        if (class_exists('Petshop_Fulfillment_Source')) {
            try {
                $r = Petshop_Fulfillment_Source::resolve($pid);
                if (is_array($r) && !empty($r['source'])) return $r['source'];
                if (is_object($r) && !empty($r->source)) return $r->source;
            } catch (\Throwable $e) {}
        }
        if (get_post_meta($pid,'_vf_enabled',true)==='yes') return 'vf';
        if (get_post_meta($pid,'_zb_enabled',true)==='yes') return 'zb';
        $man = mb_strtolower(get_post_meta($pid,'_legacy_manufacturer',true));
        if (strpos($man,'quattro')!==false) return 'quattro';
        if (strpos($man,'prins')!==false) return 'prins';
        if (strpos($man,'belacor')!==false) return 'belcor_tofu';
        return 'legacy';
    }
}

// === 1. Bundle CTA kortelė (v2: stipresnis vizualas, "nuo X€" kaina) ===
add_shortcode('psc_sprendimas_bundle', function($atts){
    $atts = shortcode_atts(array('id'=>0, 'label'=>'Susidėk pats'), $atts);
    $id = intval($atts['id']);
    if (!$id || get_post_status($id) !== 'publish') return '';
    $product = wc_get_product($id);
    if (!$product) return '';
    $url = get_permalink($id);
    $img_id = $product->get_image_id();
    $img = $img_id ? wp_get_attachment_image_url($img_id, 'medium') : '';
    $price = wc_price($product->get_price());
    ob_start(); ?>
    <a href="<?php echo esc_url($url); ?>" class="psc-sol-card">
        <?php if ($img): ?>
        <div class="psc-sol-card-img"><img src="<?php echo esc_url($img); ?>" alt="<?php echo esc_attr($product->get_name()); ?>" loading="lazy"></div>
        <?php else: ?>
        <div class="psc-sol-card-img psc-sol-card-img-icon">🎁</div>
        <?php endif; ?>
        <div class="psc-sol-card-body">
            <div class="psc-sol-card-title"><?php echo esc_html($product->get_name()); ?></div>
            <div class="psc-sol-card-price">nuo <?php echo wp_kses_post($price); ?></div>
            <span class="psc-sol-card-btn">🎁 <?php echo esc_html($atts['label']); ?></span>
        </div>
    </a>
    <?php return ob_get_clean();
});

// === 2. Nuoroda į kategoriją (outline mygtukas) ===
add_shortcode('psc_sprendimas_kategorija', function($atts){
    $atts = shortcode_atts(array('slug'=>'', 'label'=>''), $atts);
    if (!$atts['slug']) return '';
    $term = get_term_by('slug', $atts['slug'], 'product_cat');
    if (!$term) return '';
    $url = get_term_link($term);
    if (is_wp_error($url)) return '';
    $label = $atts['label'] ?: $term->name;
    return '<a href="'.esc_url($url).'" class="psc-sol-btn psc-sol-btn-outline-light">'.esc_html($label).'</a>';
});

// === 3. Saugi nuoroda (be add-to-cart) ===
add_shortcode('psc_sprendimas_nuoroda', function($atts){
    $atts = shortcode_atts(array('title'=>'', 'url'=>''), $atts);
    if (!$atts['title'] || !$atts['url']) return '';
    return '<a href="'.esc_url($atts['url']).'" class="psc-sol-btn psc-sol-btn-outline">'.esc_html($atts['title']).'</a>';
});

// === 4. "Kada verta sunerimti?" saugiklio blokas ===
add_shortcode('psc_sprendimas_sunerimti', function($atts, $content=''){
    if (!trim((string)$content)) return '';
    ob_start(); ?>
    <div class="psc-sol-warning">
        <div class="psc-sol-warning-title">⚠️ Kada verta sunerimti?</div>
        <div class="psc-sol-warning-text"><?php echo wp_kses_post(wpautop(trim($content))); ?></div>
    </div>
    <?php return ob_get_clean();
}, 10);

// === 5. Kuruotas produktų grid'as — TIK source=av ===
add_shortcode('psc_sprendimas_produktai', function($atts){
    $atts = shortcode_atts(array(
        'cat' => '', 'source' => 'av', 'limit' => 12, 'min_items' => 4,
        'fallback_url' => '', 'fallback_text' => '',
    ), $atts);

    $allowed = array('av');
    if (!in_array($atts['source'], $allowed, true)) {
        if ($atts['fallback_url'] && $atts['fallback_text']) {
            return '<a href="'.esc_url($atts['fallback_url']).'" class="psc-sol-btn psc-sol-btn-outline">'.esc_html($atts['fallback_text']).'</a>';
        }
        return '';
    }
    if (!$atts['cat']) return '';

    $limit = max(1, intval($atts['limit']));
    $min_items = max(0, intval($atts['min_items']));

    $q = new WP_Query(array(
        'post_type'=>'product','post_status'=>'publish','posts_per_page'=>-1,'fields'=>'ids',
        'tax_query'=>array(array('taxonomy'=>'product_cat','field'=>'slug','terms'=>$atts['cat'])),
    ));
    $ids = $q->posts; wp_reset_postdata();

    $filtered = array();
    foreach ($ids as $pid) {
        if (psc_sprendimas_resolve_source($pid) !== 'legacy') continue;
        $p = wc_get_product($pid);
        if ($p && $p->is_in_stock()) $filtered[] = $pid;
    }

    if (count($filtered) < $min_items) {
        if ($atts['fallback_url'] && $atts['fallback_text']) {
            return '<a href="'.esc_url($atts['fallback_url']).'" class="psc-sol-btn psc-sol-btn-outline">'.esc_html($atts['fallback_text']).'</a>';
        }
        return '';
    }

    usort($filtered, function($a,$b){ return strcasecmp(get_the_title($a), get_the_title($b)); });
    $filtered = array_slice($filtered, 0, $limit);

    ob_start();
    echo '<div class="psc-sol-grid">';
    foreach ($filtered as $pid) {
        $product = wc_get_product($pid);
        if (!$product) continue;
        $img = wp_get_attachment_image_url($product->get_image_id(), 'medium');
        if (!$img) $img = wc_placeholder_img_src();
        echo '<div class="psc-sol-product" data-src="av">';
        echo '<a href="'.esc_url(get_permalink($pid)).'" class="psc-sol-product-img"><img src="'.esc_url($img).'" alt="'.esc_attr($product->get_name()).'" loading="lazy"></a>';
        echo '<a href="'.esc_url(get_permalink($pid)).'" class="psc-sol-product-title">'.esc_html($product->get_name()).'</a>';
        echo '<div class="psc-sol-product-price">'.wp_kses_post($product->get_price_html()).'</div>';
        echo '<div class="psc-sol-product-cart">'.do_shortcode('[add_to_cart id="'.$pid.'" show_price="false" style=""]').'</div>';
        echo '</div>';
    }
    echo '</div>';
    return ob_get_clean();
});

// === 5b. Krypties kortelė (navigacinė — be produktų, be kainų, be add-to-cart) ===
add_shortcode('psc_sprendimas_krypties_kortele', function($atts){
    $atts = shortcode_atts(array(
        'title'          => '',
        'text'           => '',
        'icon'           => '',
        'dog_title'      => '',
        'dog_url'        => '',
        'cat_title'      => '',
        'cat_url'        => '',
        'single_title'   => '',
        'single_url'     => '',
        'secondary_text' => '',
        'secondary_url'  => '',
    ), $atts);
    if (!$atts['title']) return '';
    ob_start(); ?>
    <div class="psc-sol-krypt">
        <div class="psc-sol-krypt-head">
            <?php if ($atts['icon']): ?><span class="psc-sol-krypt-icon"><?php echo esc_html($atts['icon']); ?></span><?php endif; ?>
            <span class="psc-sol-krypt-title"><?php echo esc_html($atts['title']); ?></span>
        </div>
        <?php if ($atts['text']): ?><p class="psc-sol-krypt-text"><?php echo esc_html($atts['text']); ?></p><?php endif; ?>
        <div class="psc-sol-krypt-btns">
            <?php if ($atts['dog_title'] && $atts['dog_url']): ?>
                <a href="<?php echo esc_url($atts['dog_url']); ?>" class="psc-sol-krypt-btn"><?php echo esc_html($atts['dog_title']); ?></a>
            <?php endif; ?>
            <?php if ($atts['cat_title'] && $atts['cat_url']): ?>
                <a href="<?php echo esc_url($atts['cat_url']); ?>" class="psc-sol-krypt-btn"><?php echo esc_html($atts['cat_title']); ?></a>
            <?php endif; ?>
            <?php if ($atts['single_title'] && $atts['single_url']): ?>
                <a href="<?php echo esc_url($atts['single_url']); ?>" class="psc-sol-krypt-btn"><?php echo esc_html($atts['single_title']); ?></a>
            <?php endif; ?>
            <?php if ($atts['secondary_text'] && $atts['secondary_url']): ?>
                <a href="<?php echo esc_url($atts['secondary_url']); ?>" class="psc-sol-krypt-btn psc-sol-krypt-btn-outline"><?php echo esc_html($atts['secondary_text']); ?></a>
            <?php endif; ?>
        </div>
        <?php if ($atts['secondary_text'] && !$atts['secondary_url']): ?>
            <span class="psc-sol-krypt-secondary-plain"><?php echo esc_html($atts['secondary_text']); ?></span>
        <?php endif; ?>
    </div>
    <?php return ob_get_clean();
});

// === 6. Footer product widget'ų slėpimas Sprendimai puslapiuose ===
// Veikia visiems 6 puslapiams, nes visi bus "Sprendimai" (34253) vaikai -> body class parent-pageid-34253
add_action('wp_head', function(){
    if (!is_page()) return;
    if (!(is_page(34253) || (function_exists('get_post') && get_post() && get_post()->post_parent == 34253))) return;
    echo '<style>footer .footer-widgets.footer-1{display:none !important;}</style>';
}, 25);

// === Stiliai (bendri visiems 6 "Sprendimai" puslapiams) ===
