        background:linear-gradient(135deg,#3a6b46,#2f5a3a);
        border-radius:16px; padding:20px 30px; margin:20px 0 28px;
        box-shadow:0 6px 20px rgba(47,90,58,.18);
    }
    .psc-sol-cta-banner-title{ color:#fff; font-size:20px; font-weight:800; margin:0 0 16px; }
    .psc-sol-cols{display:flex;gap:20px;flex-wrap:wrap;}
    .psc-sol-col{flex:1 1 280px;min-width:260px;}
