    .psc-sol-krypt-btn:hover{transform:translateY(-2px);color:#fff !important;}
    .psc-sol-krypt-btn-outline{background:#fff;color:#2f5a3a !important;border:2px solid #2f5a3a;padding:8px 20px;}
